      'IT-regression: the trapped production sequence now submits',
      () async {
        await openSheet();
        await typeSecret('s3cr3t-TOKEN-42');
        harness.sendEnter();
        await harness.waitForText(
          'turn-complete',
          timeout: const Duration(seconds: 30),
