      final padded = [_olderRow.padRight(120)];
      final erased = [_olderRow];
      expect(
        padded,
        isNot(equals(erased)),
        reason: 'precondition: the raw buffer really does differ',
      );
      expect(frameContentLines(padded), frameContentLines(erased));
