      final frame = ['  indented  ', '', _olderRow];
      expect(frameContentLines(frame), ['  indented', '', _olderRow]);
    });
  });

  group('emulator materialization (the gh-982 artifact class)', () {
    test('same row text reads padded or unpadded depending on the '
