      // frame-closed, so the `│` guard pins this to the sheet's own row.
      // One repaint can still race the verification window's last poll;
      // re-settle once before failing.
      var row = valueRow();
      if (row == null) {
        await harness.waitForOutput(settleMs: 300);
        row = valueRow();
      }
      if (row == null) {
        throw StateError(
