  /// current terminal screen, then returns the raw output. The screen check
  /// catches text whose raw form is interrupted by ANSI styling.","path":"test/integration/pty_harness.dart"}

{"content":"// Unit proof for the gh-1244 review-thread fix: `typeSecret` must
// synchronize on a STABLE screen property, not a snapshot read after a
// silently-timing-out `waitForOutput` — on a loaded runner the painted
// frame can still be mid-echo (e.g. 13 of 15 bullets). The anchor is the
// sheet's frame-closed masked value row (`maskedValueRow`): bullets are
// append-only while typing, so waiting for the full N-bullet row on the
// SCREEN is a monotone synchronization point, and the `│` guard pins the
// match to the sheet's own row — the history's tool row
// (`• request_secret · …`) is not frame-closed and must never match.
//
// Top-level and pure (like `frameContentLines`) so the row-anchor rule is
// provable without a PTY. Runs in the DEFAULT suite (no integration tag).
@TestOn('vm')
library;

import 'package:test/test.dart';

import 'pty_harness.dart';

void main() {
  group('maskedValueRow', () {
    test('finds the frame-closed bullet row among history and chrome', () {
      const screen = '''
[Model] test-model
● request_secret · to call the upstream API
┌ Credential request ──────────────┐
│ Name  MY_SERVICE_TOKEN           │
│ Value  > •••••••••••••••••       │
└──────────────────────────────────┘
''';
      expect(maskedValueRow(screen), '│ Value  > •••••••••••••••••       │');
    });

    test('ignores the history tool row — a lone bullet not frame-closed', () {
      const screen = '''
● request_secret · MY_SERVICE_TOKEN
┌ Credential request ──┐
│ Name  MY_SERVICE_TOKEN │
''';
      expect(maskedValueRow(screen), isNull);
    });

    test('a frame-closed row without bullets does not match (e.g. the '
        'name row)', () {
      const screen = '''
┌ Credential request ──┐
│ Name  MY_SERVICE_TOKEN │
│ Value  >               │
''';
      expect(maskedValueRow(screen), isNull);
    });

    test('empty screen never matches', () {
      expect(maskedValueRow(''), isNull);
    });
  });
}
","path":"test/integration/pty_harness_settled_output_test.dart"}

{"newText":"/// The secret sheet's frame-closed masked value row on a captured screen
/// (gh-1244): the line carrying bullets AND closing with the `│` border.
/// The history's tool row (`• request_secret · …`) is not frame-closed,
/// so the `│` guard pins the match to the sheet's own row. Null when no
/// such row is painted (sheet not open, or the row's closing border has
/// not landed in this frame yet). Top-level (like [frameContentLines])
/// so the row-anchor rule is unit-testable without a PTY.
String? maskedValueRow(String screen) => screen
    .split('\n')
    .where((l) => l.contains('•') && l.trimRight().endsWith('│'))
    .firstOrNull;

/// The visible viewport with each line's trailing blank cells stripped —
/// the CONTENT-faithful view for cross-frame equality (gh-982).","oldText":"/// The visible viewport with each line's trailing blank cells stripped —
