      final written = Terminal(maxLines: 100)
        ..resize(120, 24)
        ..write('\x1b[5;1H${_olderRow.padRight(120)}');
      final erased = Terminal(maxLines: 100)
        ..resize(120, 24)
        ..write('\x1b[5;1H${_olderRow.padRight(120)}')
        ..write('\x1b[5;1H$_olderRow\x1b[K');

